x = (2*rand(1,200)-1).*sqrt(pi/2);
y = (2*rand(1,200)-1).*sqrt(pi/2);
[X, Y] = meshgrid(x, y);
Z = sin(X.^2 + Y.^2);

figure; %[output:63fe96cd]
surf(X, Y, Z); %[output:63fe96cd]
shading interp; %[output:63fe96cd]
colormap parula; %[output:63fe96cd]
view(15, 30); %[output:63fe96cd]
xlabel('X'); %[output:63fe96cd]
ylabel('Y'); %[output:63fe96cd]
zlabel('Z'); %[output:63fe96cd]
title('f(x,y) = sin(x^2 + y^2)'); %[output:63fe96cd]
grid on; %[output:63fe96cd]

x2 = -1:0.05:1;
y2 = -1:0.05:1;
[X2, Y2] = meshgrid(x2, y2);
R = sqrt(X2.^2 + Y2.^2);
Z2 = exp(R.^2);

figure; %[output:3d3b46a1]
surf(X2, Y2, Z2); %[output:3d3b46a1]
shading flat; %[output:3d3b46a1]
colormap jet; %[output:3d3b46a1]
view(20, 30); %[output:3d3b46a1]
xlabel('X'); %[output:3d3b46a1]
ylabel('Y'); %[output:3d3b46a1]
zlabel('Z'); %[output:3d3b46a1]
title('z(r) = e^{r^2}'); %[output:3d3b46a1]
grid on; %[output:3d3b46a1]

x3 = -2:0.1:2;
y3 = -2:0.1:2;
[X3, Y3] = meshgrid(x3, y3);
Z3 = 1 - (X3.^2 + Y3.^2);

figure; %[output:2d674dfd]
subplot(2,2,1); %[output:2d674dfd]
surf(X3, Y3, Z3); %[output:2d674dfd]
colormap(gca, 'autumn'); %[output:2d674dfd]
title('Colormap: autumn'); %[output:2d674dfd]

subplot(2,2,2); %[output:2d674dfd]
surf(X3, Y3, Z3); %[output:2d674dfd]
colormap(gca, 'bone'); %[output:2d674dfd]
title('Colormap: bone'); %[output:2d674dfd]

subplot(2,2,3); %[output:2d674dfd]
surf(X3, Y3, Z3); %[output:2d674dfd]
colormap(gca, [0.2 0.6 0.8]); %[output:2d674dfd]
title('Color code 1'); %[output:2d674dfd]

subplot(2,2,4); %[output:2d674dfd]
surf(X3, Y3, Z3); %[output:2d674dfd]
colormap(gca, [0.8 0.3 0.2]); %[output:2d674dfd]
title('Color code 2'); %[output:2d674dfd]

